window.RP_SESSION={"id":"S-f7cf558265f1","messages":[{"id":"RP-III-0005116","time":"2026-01-09T09:40:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"... 예쁘네, 이거...\"\n\n그녀는 조금은 도톰해진 돈주머니를 들고선 금은방 앞에서 서성였습니다. 실링 여럿과 코퍼만 잔뜩 들어 찰랑였습니다. 최근 잡다한 의뢰들을 처리하며 번 용돈이었습니다.\n\n이내 그녀는 맘에 쏙 드는 반지를 두 쌍 발견했습니다. 햇빛에 비쳐 반짝이는 자태의 은반지는 순식간에 그녀의 마음을 사로잡아버렸습니다.\n\n\"... 이거로 큰 사이즈 하나랑... 저거로 하나 해주세요.\"\n.\n.\n.\n\n\"아, 그리고 저것도요.\"\n\n주머니가 순식간에 가벼워질 정도의 그녀에겐 무서울만한 가격... 하지만 상관없었습니다.\n\n그녀는 방긋 웃으며 금세 값을 지불하곤 팔찌 하나와 은반지 두 쌍을 가방에 집어넣었습니다.\n팔찌는 제 어머니를 위해, 사이즈도 모르는 은반지는 제 연인을 위하여 행복한 미소를 머금곤 종종걸음으로 길드로 돌아갑니다.\n\n\"포테씨도 엄청 엄청 좋아해 줄 거고 그리고 데미안 씨도 오시면 드려야지......\"\n\n텅 빈 주머니에, 그녀는 행복을 채워 넣었습니다.\n\n\n'..","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0005117","time":"2026-01-09T09:40:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0005118","time":"2026-01-09T09:40:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"\"아주 멋진 한판이었어!\"","characters":[]}]};
